pub struct AdfLatticeValueMeetTopTool;
impl AdfLatticeValueMeetTopTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "adf_lattice_value_meet_top".to_string(), description: "LatticeValue::meet(Top, Const(x)).".to_string(), input_schema: json!({"type":"object","properties":{"x":{"type":"integer"}},"required":["x"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for AdfLatticeValueMeetTopTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let x = args.get("x").and_then(Value::as_i64).ok_or_else(|| McpError::InvalidParams("missing 'x'".into()))?; let r = rustre_analysis_dataflow::LatticeValue::meet(&rustre_analysis_dataflow::LatticeValue::Top, &rustre_analysis_dataflow::LatticeValue::Const(x)); let (kind, val) = match r { rustre_analysis_dataflow::LatticeValue::Top => ("top", None), rustre_analysis_dataflow::LatticeValue::Const(c) => ("const", Some(c)), rustre_analysis_dataflow::LatticeValue::Bottom => ("bottom", None) }; Ok(ToolResult::text(json!({"kind":kind,"value":val,"source":"rustre_analysis_dataflow::LatticeValue::meet"}).to_string())) } }

