pub struct AdfComputeDominatorsChainTool;
impl AdfComputeDominatorsChainTool { #[must_use] pub fn definition() -> ToolDefinition { ToolDefinition { name: "adf_compute_dominators_chain".to_string(), description: "compute_dominators over a linear chain.".to_string(), input_schema: json!({"type":"object","properties":{"n":{"type":"integer"}},"required":["n"]}), parameters: Value::Null } } }
#[async_trait] impl ToolHandler for AdfComputeDominatorsChainTool { async fn call(&self, args: Value) -> Result<ToolResult, McpError> { let n = args.get("n").and_then(Value::as_u64).ok_or_else(|| McpError::InvalidParams("missing 'n'".into()))? as usize; if n == 0 { return Err(McpError::InvalidParams("n must be > 0".into())); } let successors: Vec<Vec<usize>> = (0..n).map(|i| if i + 1 < n { vec![i + 1] } else { vec![] }).collect(); let idom = rustre_analysis_dataflow::compute_dominators(n, &successors, 0); Ok(ToolResult::text(json!({"idom":idom,"n":n,"source":"rustre_analysis_dataflow::compute_dominators"}).to_string())) } }

